import { Elysia } from 'elysia';
import { cors } from '@elysiajs/cors';
import { jwt } from '@elysiajs/jwt';
import { bearer } from '@elysiajs/bearer';
import { fail, ERROR_CODES } from './src/utils/response';
import { authRoutes } from './src/routes/auth.routes';
import { expenseRoutes } from './src/routes/expense.routes';

const jwtPlugin = new Elysia\({ name: 'plugin/jwt' }\).use\(
  jwt\({ name: 'jwt', secret: 'test-jwt-secret-for-tests', exp: '15m' }\)
\);

const app = new Elysia\(\)
  .use\(cors\({ origin: true }\)\)
  .use\(jwtPlugin\)
  .use\(bearer\(\)\)
  .onError\(\({ code, error, set }\) => {
    console.log\('GLOBAL ERROR:', code, error.message\);
    switch \(code\) {
      case 'VALIDATION':
        set.status = 422;
        return fail\(error.message, ERROR_CODES.VALIDATION_ERROR\);
      case 'NOT_FOUND':
        set.status = 404;
        return fail\('Route not found', ERROR_CODES.NOT_FOUND\);
      default:
        set.status = 500;
        return fail\('Internal server error', ERROR_CODES.INTERNAL_ERROR\);
    }
  }\)
  .use\(expenseRoutes\);

const response = await app.handle\(new Request\('http://localhost/expenses'\)\);
console.log\('STATUS:', response.status\);
const body = await response.json\(\);
console.log\('BODY:', JSON.stringify\(body\)\);
